gitAssertions.cmd:
$ErrorActionPreference='Stop'
$paths=@('apps/backoffice/next-env.d.ts','apps/web/next-env.d.ts','apps/booking-web/next-env.d.ts','apps/feedback-web/next-env.d.ts','apps/yuta-pos/next-env.d.ts','apps/yuta-display/next-env.d.ts')
$rows=@(foreach($path in $paths){
 $tracked=@(git ls-files -- $path)
 $ignore=git check-ignore -v -- $path
 if($tracked.Count -or $LASTEXITCODE -ne 0 -or $ignore -notmatch ([regex]::Escape('/'+$path)+'\s')){throw "Tracking/ignore assertion failed: $path"}
 [pscustomobject]@{path=$path;lsFiles=$tracked;checkIgnore=$ignore;localExists=(Test-Path -LiteralPath $path);sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower()}
})
$removed=@(git diff --cached --diff-filter=D --name-only)
if(@(Compare-Object $removed $paths).Count -or @(git diff --cached --diff-filter=ACMRTUXB --name-only).Count){throw 'Unexpected index diff'}
$ignored=@(git ls-files -ci --exclude-standard)
if($ignored.Count){throw 'Other tracked source ignored'}
[pscustomobject]@{rows=$rows;staged=@(git diff --cached --name-status);trackedCount=@(git ls-files).Count;otherIgnored=$ignored;status=@(git status --short -- .gitignore scripts/test-pos-offline.mjs @paths)} | ConvertTo-Json -Depth 4

protection.command:
$ErrorActionPreference='Stop'
$e=Get-Content docs/reviews/next-generated-types-bootstrap/phase-1-revalidation.json -Raw | ConvertFrom-Json
$m=Get-Content docs/reviews/formalites-authorization/03-integrity.json -Raw | ConvertFrom-Json
foreach($f in $m.files){if((Get-FileHash -LiteralPath $f.path -Algorithm SHA256).Hash.ToLower() -ne $f.sha256){throw "Formalites mismatch: $($f.path)"}}
foreach($r in $e.protectionAfter.protectedHashes | Where-Object {$_.path -like '*formalites-authorization*' -or $_.path -like 'apps/backoffice/*formalites*' -or $_.path -eq 'apps/backoffice/src/server/auth/permissions.ts'}){if((Get-FileHash -LiteralPath $r.path -Algorithm SHA256).Hash.ToLower() -ne $r.sha256){throw "Protected mismatch: $($r.path)"}}
$supp=@(git ls-files --cached --others --exclude-standard -- docs/reviews/formalites-authorization openspec/changes/formalites-authorization | Sort-Object -Unique)
if(@(Compare-Object $supp $e.protectionAfter.supplemental).Count){throw 'Formalites path mismatch'}
if($m.files.Count -ne 18 -or $supp.Count -ne 17){throw 'Formalites count mismatch'}
'Formalites 4/4 implementation + 18/18 integrity + 17/17 supplemental: MATCH'

